import java.util.*;
public class Main {
    static int expected(String name){String v=name.equals("-")?"":name;return !v.isEmpty()&&v.length()<=20?200:400;}
    public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();List<String> frameworks=List.of("spring","liberty","quarkus");Map<String,Integer> fails=new LinkedHashMap<>();for(String f:frameworks)fails.put(f,0);boolean broken=false;for(int k=1;k<=n;k++){String name=s.next(),framework=s.next();int actual=s.nextInt(),want=expected(name);boolean pass=want==actual;if(!pass){fails.merge(framework,1,Integer::sum);broken=true;}System.out.println(k+" "+framework+" expected="+want+" actual="+actual+" "+(pass?"PASS":"FAIL"));}for(String f:frameworks)System.out.println(f+" "+fails.get(f));System.out.println(broken?"CONTRACT_BROKEN":"CONTRACT_OK");}
}

